{
  "name": "Modbus ADU 客户端到服务器报文解析器",
  "name_en": "Modbus ADU Client-to-Server Message Decoder",
  "manufacturer": "",
  "description": "这是一个用于解析 Modbus 协议中客户端发往服务器的应用数据单元（ADU）报文的软件协议解析组件，而非特定物理仪器。它可用于实验室或工业现场的串口/总线通信分析，帮助识别读寄存器、写多线圈、写多寄存器、读文件记录等 Modbus 请求帧。",
  "description_en": "This is a software protocol parsing component for Modbus client-to-server Application Data Unit (ADU) messages rather than a specific physical instrument. It is used in laboratory or industrial serial/bus communication analysis to identify Modbus request frames such as register reads, multiple coil writes, multiple register writes, and file record reads.",
  "actions": [
    {
      "action_name": "auto-parse",
      "description": "解析 Modbus 客户端到服务器 ADU 报文，并按功能码分派到对应的请求解析流程。",
      "description_en": "Parse a Modbus client-to-server ADU message and dispatch it to the appropriate request parser based on the function code."
    },
    {
      "action_name": "auto-parse_read_data_command",
      "description": "解析读取数据类请求，包括读取线圈、离散输入、保持寄存器或输入寄存器的命令。",
      "description_en": "Parse read-data requests, including commands for reading coils, discrete inputs, holding registers, or input registers."
    },
    {
      "action_name": "auto-parse_single_byte_request",
      "description": "解析仅包含单字节功能码、无附加参数的 Modbus 请求。",
      "description_en": "Parse a Modbus request that contains only a single-byte function code with no additional arguments."
    },
    {
      "action_name": "auto-parse_write_multiple",
      "description": "解析写多个对象的请求，包括写多个线圈或写多个寄存器。",
      "description_en": "Parse requests that write multiple items, including writing multiple coils or multiple registers."
    },
    {
      "action_name": "auto-parse_read_file_record",
      "description": "解析 Modbus 读文件记录请求（功能码 20），包括其中的子请求结构。",
      "description_en": "Parse a Modbus Read File Record request (function 20), including its sub-request structure."
    },
    {
      "action_name": "auto-parse_read_write_registers",
      "description": "解析同时读取和写入多个寄存器的复合请求（功能码 23）。",
      "description_en": "Parse a combined request that reads and writes multiple registers (function 23)."
    }
  ],
  "tag_hints": [
    "Modbus protocol",
    "serial communication analysis",
    "industrial bus decoding",
    "ADU message parsing",
    "register read/write requests",
    "protocol debugging"
  ]
}

